import unittest
import quantity_multiple as app

class Behavior(unittest.TestCase):
    def test_exact_numbers(self):
        rows=[('4.02','0.01',True),('4.021','0.01',False),('0.3','0.1',True),('-0.6','0.2',True),('0','7',True),('23','10',False),('1e-3','0.0001',True),('1.0000000000000000000001','0.1',False),('1000000000000000000000','0.01',True)]
        for v,d,w in rows:self.assertEqual(app.is_multiple(v,d),w)


if __name__ == "__main__":
    unittest.main()

class BeyondDecimalContext(unittest.TestCase):
    def test_unrounded_quotients(self):
        self.assertFalse(app.is_multiple('1.00000000000000000000000000000000000000001', '1'))
        self.assertTrue(app.is_multiple('1e50', '0.01'))
        self.assertFalse(app.is_multiple('1e-40', '3e-41'))
        self.assertTrue(app.is_multiple('-0e-20', '2.5e-30'))

